from decimal import Decimal, ROUND_HALF_UP


def text(value):
    """Anything a source or an extractor gives us, as a comparable string."""
    return "" if value is None else str(value).strip()


def empty(value):
    return text(value) == ""


def cents(value):
    """Amounts compare in whole cents, half up."""
    return int((Decimal(str(value)) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def evaluate(instance, sources, others):
    """The printed VAT must be the base times the rate, within one cent."""
    if (
        empty(instance.get("base"))
        or empty(instance.get("vat_rate"))
        or empty(instance.get("vat_amount"))
    ):
        return {"fires": False, "reason": ""}
    expected = (
        Decimal(str(instance.get("base")))
        * Decimal(str(instance.get("vat_rate")))
        / Decimal(100)
    )
    if abs(cents(instance.get("vat_amount")) - cents(expected)) <= 1:
        return {"fires": False, "reason": ""}
    return {"fires": True, "reason": "VAT_AMOUNT_MISMATCH"}

