        return None
    try:
        return date(int(parts[0]), int(parts[1]), int(parts[2]))
    except ValueError:
        return None


def fires(reason):
    return {"fires": True, "reason": reason}


def passes():
    return {"fires": False, "reason": ""}

def evaluate(instance, sources, others):
    """Another invoice in this process claims the same order."""
    order = key(instance.get("purchase_order"))
    if not order:
        return passes()
    twins = [
        text(other.get("_instance"))
        for other in others
        if key(other.get("purchase_order")) == order
    ]
    if twins:
        return fires("Same order as: " + ", ".join(sorted(twins)))
    return passes()
```

## Guidance for this use case
Symbols come from OCR and document parsing: numbers may arrive as text with a comma or a dot as decimal separator; never assume a type, convert as the description says. Put the helpers you need (normalise, cents) inside the code: there is no shared library.

